  "البلاغ الذي يصل خارج النظام — هاتفًا أو شفاهةً — يُسجَّل هنا ليدخل الدورة، فلا يبقى في ذاكرة أحد.": "A report that arrives outside the system — by phone or word of mouth — is logged here so it enters the cycle and does not rest in anyone’s memory.",
