  "التحقق من العدد قبل الدخول": "Verify the head count before entry",
  "التحقّق من الهوية": "Identity verification",
  "التحقق من بطاقات نُسك": "Verifying Nusuk cards",
  "التحقق من بلاغ «حافلة / لوحة خاطئة» ومطابقة المجموعة والحافلة والموقع مع برنامج الحركة، والتنسيق مع النقل والبعثة والكنترول لتصحيح الحالة.": "Verify the “wrong bus / board” report, match the group, bus and location against the movement programme, and coordinate with transport, the mission and Control to put it right.",
  "التحقق من بلاغ «موقع إنزال خاطئ» ومطابقة المجموعة والحافلة والموقع مع برنامج الحركة، والتنسيق مع النقل والبعثة والكنترول لتصحيح الحالة.": "Verify the “wrong drop-off point” report, match the group, bus and location against the movement programme, and coordinate with transport, the mission and Control to put it right.",
  "التحقق من بلاغ «نقص عدد الحافلات» ومطابقة المجموعة والحافلة والموقع مع برنامج الحركة، والتنسيق مع النقل والبعثة والكنترول لتصحيح الحالة.": "Verify the “shortfall in buses” report, match the group, bus and location against the movement programme, and coordinate with transport, the mission and Control to put it right.",
  "التحقّق من جاهزية الأدوار": "Checking the floors are ready",
  "التحقق من سبب تأخر الحافلة أو المجموعة وموقعها، والتنسيق مع مسؤول النقل والكنترول لتأكيد الوصول ومتابعة أثر التأخير على المهمة.": "Establish why the bus or group is late and where it is, and coordinate with the transport officer and Control to confirm arrival and track the delay’s effect on the task.",
  "التحقق من سبب تأخر الدينات، والتنسيق مع مسؤول النقل والكنترول لتأكيد الوصول ومتابعة أثر التأخير على المهمة.": "Establish why the luggage vans are late and coordinate with the transport officer and Control to confirm arrival and track the delay’s effect on the task.",
  "التحقق من سبب تأخر المرشد ومتابعة أثر التأخير على المهمة.": "Establish why the guide is late and track the delay’s effect on the task.",
