  "التذاكرُ بلا آليّاتِ تصعيد — لا خطورةَ ولا مهلةَ ولا مسار.": "Tickets have no escalation mechanism — no severity, no deadline, no path.",
  "التذاكرُ بلا آليّاتِ تصعيد — لا خطورةَ ولا مهلةَ ولا مسار. تصنيفٌ يختاره الحاجّ، ووصفٌ يكتبه، والكنترولُ يعالجها بما يراه.": "Tickets have no escalation mechanism — no severity, no deadline, no path. A category the pilgrim chooses, a description they write, and Control handles it as it sees fit.",
