  "القالب الذي تنزّله هو الذي ترفعه — العناوين نفسها وبالترتيب نفسه.": "The template you download is the one you upload — the same headers in the same order.",
  "القالب الذي تنزّله هو الذي ترفعه — العناوين نفسها وبالترتيب نفسه. وما ينقصه بيانٌ يُوسَم أحمر ولا تُعتمد الدفعة حتى يكتمل.": "The template you download is the one you upload — the same headers in the same order. Anything with missing data is flagged red, and the batch is not approved until it is complete.",
  "القالب يُبنى مرّة، ويُجدوَل مرارًا على من شئت وفي أي وقت": "A template is built once and scheduled repeatedly, to whomever you wish and at any time",
  "القالب يُبنى مرّة، ويُجدوَل، ويُسنَد لمن هو في شِفته، ويُقرأ أثره على الجهة": "A template is built once, scheduled, assigned to whoever is on shift, and its effect on the organisation is read",
  "القالب يُضيف شروطه الثلاث مراحل دفعةً واحدة. وما كان موجودًا لا يُكرَّر.": "The template adds its conditions across the three stages in one go. Anything already present is not duplicated.",
