  "يُخصم من قيمة العقد ما نسبته اثنان في المئة عن كل ساعة تأخير عن الموعد المحدّد،": "Two per cent of the contract value is deducted for every hour of delay past the set time,",
  "يُخصم من قيمة العقد ما نسبته اثنان في المئة عن كل ساعة تأخير، ويحقّ للطرف": "Two per cent of the contract value is deducted for every hour of delay, and the second",
  "يُخصم من قيمة العقد ما نسبته اثنان في المئة عن كل ساعة تأخير، ويحقّ للطرف الثاني فسخ العقد عند تكرار المخالفة ثلاث مرّات في الموسم الواحد.": "Two per cent of the contract value is deducted for every hour of delay, and the second party may terminate the contract if the breach recurs three times in a single season.",
  "يُخصم من قيمة العقد ما يقابل ليلةً كاملة عن كل غرفة تُسلَّم غير مطابقة للمواصفات،": "A full night’s value is deducted from the contract for every room handed over not meeting specification,",
  "يُدخل ويُصدِّر ويعتمد الاكسترا كوتا — لا غير": "Enters, exports and approves extra quota — nothing else",
  "يدور بين اللوحات كل {n} ثانية": "Rotates between boards every {n} seconds",
  "يديره الكنترول وحده — لا يراه ليدر ولا يختار منه": "Managed by Control alone — no leader sees it or picks from it",
