  "التحقق من بلاغ «حافلة / لوحة خاطئة» ومطابقة المجموعة والحافلة والموقع مع برنامج الحركة، والتنسيق مع النقل والبعثة والكنترول لتصحيح الحالة.": "Sahkan laporan “bas / papan salah”, padankan kumpulan, bas dan lokasi dengan program pergerakan, dan selaraskan dengan pengangkutan, misi dan Kawalan untuk membetulkannya.",
  "التحقق من بلاغ «موقع إنزال خاطئ» ومطابقة المجموعة والحافلة والموقع مع برنامج الحركة، والتنسيق مع النقل والبعثة والكنترول لتصحيح الحالة.": "Sahkan laporan “lokasi penurunan salah”, padankan kumpulan, bas dan lokasi dengan program pergerakan, dan selaraskan dengan pengangkutan, misi dan Kawalan untuk membetulkannya.",
  "التحقق من بلاغ «نقص عدد الحافلات» ومطابقة المجموعة والحافلة والموقع مع برنامج الحركة، والتنسيق مع النقل والبعثة والكنترول لتصحيح الحالة.": "Sahkan laporan “kekurangan bas”, padankan kumpulan, bas dan lokasi dengan program pergerakan, dan selaraskan dengan pengangkutan, misi dan Kawalan untuk membetulkannya.",
  "التحقّق من جاهزية الأدوار": "Memastikan tingkat telah sedia",
  "التحقق من سبب تأخر الحافلة أو المجموعة وموقعها، والتنسيق مع مسؤول النقل والكنترول لتأكيد الوصول ومتابعة أثر التأخير على المهمة.": "Pastikan sebab bas atau kumpulan lewat dan di mana ia berada, dan selaraskan dengan pegawai pengangkutan serta Kawalan untuk mengesahkan ketibaan dan menjejaki kesan kelewatan terhadap tugas.",
  "التحقق من سبب تأخر الدينات، والتنسيق مع مسؤول النقل والكنترول لتأكيد الوصول ومتابعة أثر التأخير على المهمة.": "Pastikan sebab van bagasi lewat dan selaraskan dengan pegawai pengangkutan serta Kawalan untuk mengesahkan ketibaan dan menjejaki kesan kelewatan terhadap tugas.",
