  "التذاكرُ بلا آليّاتِ تصعيد — لا خطورةَ ولا مهلةَ ولا مسار. تصنيفٌ يختاره الحاجّ، ووصفٌ يكتبه، والكنترولُ يعالجها بما يراه.": "Tiket tiada mekanisme eskalasi — tiada tahap keseriusan, tiada tempoh, tiada laluan. Kategori yang dipilih jemaah, keterangan yang ditulisnya, dan Kawalan mengendalikannya sebagaimana yang difikirkan wajar.",
