  "توجيه البلاغ إلى المشرف للتحقق من نظافة الغرف والمرافق ومعالجة الحالة مع إدارة الفندق": "Halakan laporan kepada penyelia untuk mengesahkan kebersihan bilik dan kemudahan serta menanganinya dengan pengurusan hotel",
