  "توجيه البلاغ لـ الليدر لتقييم الحالة وتوجيهها للجهة المعنية لتقديم الرعاية وتحويلها عند الحاجة": "Halakan laporan kepada ketua untuk menilai kes dan merujuknya kepada pihak berkaitan bagi rawatan, serta memindahkannya jika perlu",
  "توجيه البلاغ لـ الليدر لتوفير كشف المغادرة من مركز الخدمة": "Halakan laporan kepada ketua untuk mendapatkan manifes pelepasan dari pusat perkhidmatan",
