  "توجيه البلاغ لـ الليدروجمع البيانات الخاصة بالحاج ويحدد الكنترول موقع الحاج , والتنسيق للبحث عنه": "Halakan laporan kepada ketua dan kumpulkan butiran jemaah; Kawalan menentukan lokasi jemaah dan menyelaras pencarian",
  "توجيه البلاغ لـ المشرف لتوفير الكرسي المتحرك ومتابعة وصوله للحاج.": "Halakan laporan kepada penyelia untuk menyediakan kerusi roda dan memastikan ia sampai kepada jemaah.",
  "توجيه البلاغ للكنترول وتوثيق الموعد الحالي والتعديل المطلوب وسببه، ومراجعته مع الجهة المختصة قبل تحديث الجدول وإبلاغ الأطراف المعنية.": "Halakan laporan kepada Kawalan, dokumenkan waktu semasa, perubahan yang diminta dan sebabnya, dan semak bersama pihak berkaitan sebelum mengemas kini jadual dan memaklumkan pihak terlibat.",
  "توجيه البلاغ للمسؤول النقل لمتابعة عطل الحافلة مع مسؤول النقل وتوفير البديل حسب الحالة، وإبلاغ الكنترول بأثره على المهمة.": "Halakan laporan kepada pegawai pengangkutan untuk menyusuli kerosakan bas, menyediakan ganti mengikut keadaan, dan memaklumkan Kawalan tentang kesannya terhadap tugas.",
  "توجيه البلاغ للمشرف لحصر الكمية الناقصة ومتابعة توفير الكمية المطلوبة مع توثيق العجز": "Halakan laporan kepada penyelia untuk mengira kekurangan, mendapatkan kuantiti yang diperlukan dan mendokumenkan defisit",
  "توجيه البلاغ للمشرف لمتابعة الإصلاح مع إدارة الفندق": "Halakan laporan kepada penyelia untuk menyusuli pembaikan dengan pengurusan hotel",
  "توجيه البلاغ للمشرف لمتابعة الإصلاح مع إدارة المشاعر": "Halakan laporan kepada penyelia untuk menyusuli pembaikan dengan pihak tapak suci",
